class Cache
  Entry = Struct.new(:payload, :stale)

  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    entry = Entry.new(payload, stale)
    @store[key] = pack(entry)
  end

  def read(key)
    return nil unless @store.key?(key)

    unpack(@store[key]).payload
  end

  def sweep
    @store.reject! do |_key, packed|
      unpack(packed).stale
    end
  end

  private

  def pack(entry)
    @packer ? @packer.dump(entry) : entry
  end

  def unpack(packed)
    @packer ? @packer.load(packed) : packed
  end
end
