class OpenRecord
  def initialize(**attrs)
    @attrs = attrs
  end

  def method_missing(name, *args)
    name_s = name.to_s
    if name_s.end_with?('=')
      @attrs[name_s.chomp('=').to_sym] = args.first
    elsif @attrs.key?(name)
      @attrs[name]
    else
      super
    end
  end

  def respond_to_missing?(name, include_private = false)
    name_s = name.to_s
    name_s.end_with?('=') || @attrs.key?(name) || super
  end
end
