module Memoizer
  def self.wrap(&computation)
    Wrapper.new(computation)
  end

  class Wrapper
    def initialize(computation)
      @computation = computation
      @mutex = Mutex.new
      @called = false
    end

    def call(*args, **kwargs, &block)
      @mutex.synchronize do
        unless @called
          @result = @computation.call(*args, **kwargs, &block)
          @called = true
        end
      end

      @result
    end
  end
end
