class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  # Stores +payload+ under +key+. If +stale+ is true, the entry will be removed
  # by the next call to #sweep.
  def write(key, payload, stale: false)
    entry = { payload: payload, stale: stale }
    @store[key] = @packer ? @packer.dump(entry) : entry
  end

  # Returns the payload most recently stored under +key+,
  # or nil if the key was never written or has been removed by #sweep.
  def read(key)
    raw = @store[key]
    return nil unless raw

    entry = @packer ? @packer.load(raw) : raw
    entry[:payload]
  end

  # Removes every entry whose #write call passed stale: true.
  # Leaves all other entries in place.
  def sweep
    @store.delete_if do |_key, raw|
      entry = @packer ? @packer.load(raw) : raw
      entry[:stale] == true
    end
  end
end
